Here is the structured output based on the analyzed document:

{
  "document_metadata": {
    "title": "SAP US Wind Lease OCS-A 0490",
    "document_number": "May 4, 2020, Revised October 2020",
    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Technical",
      "requirement": "The instrument will be mobilized from Avalon, NJ. Once prepared, the buoy would be transported to the installation site on the deck of the deployment vessel. All gear will be firmly secured to the deck with chain binders to appropriately rated pad eyes and hold points before transport to the deployment site.",
      "scope": "Offshore wind farm deployment",
      "source": "SAP US Wind Lease OCS-A 0490",
      "related_domains": ["Technical", "Safety"]
    },
    {
      "type": "Technical",
      "requirement": "Once on site, the vessel will deploy the system using the \"anchor last\" method, in which the FLS200 is deployed over the stern while the vessel maintains slow speed ahead. At 1 nm distance from the site the buoy will be lifted to the water behind the vessel. Approximately 50m of chain will be slowly released from the vessel to serve as a tow line for the buoy. The vessel will then slowly approach the site while towing the buoy behind. Once on position the crew will increase the amount of chain out by releasing sections in a controlled manner. This process will continue until all chain is overboard and the anchor remains on deck. The anchor will be slowly lowered to the seabed utilizing the mooring chain once confirmation of positioning has been obtained. All equipment will be deployed in a highly controlled manner; at no time during the operation are chain or the anchor permitted to \"free-fall\". The mooring system will be secured to the vessel at a minimum of two points at all times, to mitigate runaway hardware in the case of a component failure.",
      "scope": "Offshore wind farm deployment",
      "source": "SAP US Wind Lease OCS-A 0490",
      "related_domains": ["Technical", "Safety"]
    }
  ],
  "regulatory_entities": [
    {
      "entity_name": "Bureau of Ocean Energy Management (BOEM)",
      "jurisdiction": "Federal",
      "role": "Regulator and authority for offshore wind leases"
    }
  ]
}

